			"body[data-dsh-denia] [data-skin-chrome='sidebar-mascot']{position:absolute;bottom:calc(48vh + 24px + var(--denia-chibi-offset-y,0px));left:calc(var(--denia-sidebar-width,280px) + 8px + 8vw);transform:translateX(-50%);width:var(--denia-chibi-size,120px);height:var(--denia-chibi-size,120px);border-radius:8px;opacity:0.9;transition:opacity 0.3s,bottom 0.3s ease,left 0.3s ease,width 0.3s ease,height 0.3s ease;pointer-events:none;z-index:2;object-fit:cover}",
