			"@keyframes denia-bubble-rise{0%{transform:translateY(0) translateX(0) scale(0.3);opacity:0}8%{opacity:0.8}25%{transform:translateY(-25vh) translateX(12px) scale(0.6)}50%{transform:translateY(-50vh) translateX(-10px) scale(0.85);opacity:0.6}75%{transform:translateY(-75vh) translateX(8px) scale(1);opacity:0.3}95%{opacity:0.1}100%{transform:translateY(-110vh) translateX(0) scale(1.15);opacity:0}}",
