			"@keyframes denia-bubble-rise-bg{0%{transform:translateY(0) scale(0.2);opacity:0}10%{opacity:0.4}50%{opacity:0.25}90%{opacity:0.05}100%{transform:translateY(-110vh) scale(0.7);opacity:0}}",
			"",
