		function decorateThemeToggle() {
			var buttons = document.querySelectorAll("button, [role='button'], [role='switch'], label");
			for (var i = 0; i < buttons.length; i++) {
				var el = buttons[i];
				if (el.getAttribute("data-skin-owner") === SKIN_OWNER) continue;
				var text = (el.textContent || "").trim();
				var lower = text.toLowerCase();
				if (text.indexOf("娴呰壊") >= 0 || lower.indexOf("light") >= 0) {
					el.setAttribute("data-denia-theme-label", "light");
				} else if (text.indexOf("娣辫壊") >= 0 || lower.indexOf("dark") >= 0) {
					el.setAttribute("data-denia-theme-label", "dark");
				}
		}
			}

