				var base = isDark ? SCRIM_DARK_BASE : SCRIM_LIGHT_BASE;
				var scrim = "linear-gradient(rgba(" + (isDark ? "13,8,32" : "245,234,246") + "," + (base[0] * (1.5 - bgOp)) + ") 0%,rgba(" + (isDark ? "15,10,36" : "240,225,235") + "," + (base[1] * (1.5 - bgOp)) + ") 55%,rgba(" + (isDark ? "18,12,42" : "235,215,230") + "," + (base[2] * (1.5 - bgOp)) + ") 100%)";
